"use client";

import { useEffect } from "react";
import { AlertCircleIcon, RefreshCwIcon } from "lucide-react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { FocusOnMount } from "@/components/focus-on-mount";
import { PageHeader } from "@/components/page-header";

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    if (typeof console !== "undefined") {
      console.error("[arbx] page error:", error);
    }
  }, [error]);

  return (
    <>
      <PageHeader
        title="Something broke"
        lede="A page-level error escaped its handler. The console is still safe — only this view is affected."
      />
      <FocusOnMount>
        <Alert variant="destructive" className="mb-6">
          <AlertCircleIcon />
          <AlertTitle>{error.name || "Error"}</AlertTitle>
          <AlertDescription>
            <code className="rounded bg-destructive/10 px-1.5 py-0.5 font-mono text-xs">
              {error.message || "no message"}
            </code>
            {error.digest && (
              <div className="mt-2 text-xs text-muted-foreground">
                digest: <code className="font-mono">{error.digest}</code>
              </div>
            )}
            <p className="mt-3 text-sm">
              Reload the view, or go back to the operator console index. We never
              synthesize values to hide a fault.
            </p>
          </AlertDescription>
        </Alert>
      </FocusOnMount>

      <div className="flex flex-wrap gap-2">
        <Button type="button" onClick={reset}>
          <RefreshCwIcon /> Try again
        </Button>
        <Button type="button" variant="outline" asChild>
          <a href="/">Back to console</a>
        </Button>
      </div>
    </>
  );
}

import React from "react";
import { DeterministicAvatar } from "@/components/DeterministicAvatar";
import { shortAddr } from "@/lib/format";

/**
 * TokenChip.tsx — Pure display component for a single token in an
 * opportunity row.
 *
 * 2026-05-10 layout refresh (operator request):
 *   Always show BOTH the symbol (when known) AND the truncated address.
 *   Previous behaviour collapsed to address-only when symbol was missing,
 *   which made it impossible to tell at a glance whether a row had been
 *   enriched. The new layout uses two stacked spans:
 *     line 1:  SYMBOL   (bold, foreground)
 *     line 2:  0xabc…def (mono, muted)
 *   When the enricher has no symbol yet, line 1 renders "—" so the operator
 *   sees that the metadata is pending rather than missing the token entirely.
 *
 * R1 Mounted Snapshot compliance:
 *   - No Date.now(), no Math.random(), no window/document, no hooks.
 *   - SSR render === CSR render. Zero hydration risk.
 *
 * R8 fail-honest branching (4 cases):
 *   A. info.logo_url present         → <img> + symbol + address.
 *   B. info present, no logo, symbol → DeterministicAvatar + symbol + address.
 *   C. info.resolved_via = "failed"  → DeterministicAvatar + "—" + address.
 *   D. info = null                   → DeterministicAvatar + "—" + address.
 */

/**
 * Token Validation Engine Phase 1 — composite multi-validator output.
 * Replaces the binary verified/unverified pill with one of seven statuses.
 */
export interface TokenValidationBlock {
  status:
    | "VERIFIED"
    | "VIABLE"
    | "LOW_LIQUIDITY"
    | "ILLIQUID"
    | "NO_DATA"
    | "INVALID"
    | "PENDING";
  score: number; // 0-100
  liquidity_usd: number | null;
  volume_24h_usd: number | null;
  pair_count: number | null;
  primary_dex: string | null;
  registry_source: string | null;
  validated_at: string;
  reasons:
    | Array<{ key: string; delta: number; note: string }>
    | null;
}

/** Mirrors TokenInfoSchema from shared-ts/src/api-contracts.ts — no cross-package import. */
export interface TokenInfo {
  symbol: string | null;
  decimals: number | null;
  logo_url: string | null;
  resolved_via: "onchain_full" | "onchain_partial" | "trustwallet_only" | "failed";
  /**
   * Curated-registry verification flag set by the api-server. Optional for
   * backward compatibility with payloads emitted before 2026-05-11.
   *   true  → in Uniswap default token list AND on-chain symbol matches.
   *   false → either unknown address OR symbol-mismatch (impersonation).
   *   undefined → field not present on older payloads (treat as unknown).
   */
  verified?: boolean;
  registry_symbol?: string | null;
  registry_name?: string | null;
  verified_notes?: string[] | null;
  /**
   * Phase 1 Token Validation Engine result. When present, supersedes the
   * binary `verified` flag for rendering: the badge color + label come
   * from `validation.status` + `validation.score`. Null when the validator
   * hasn't run yet (cold start; populated by next refresh).
   */
  validation?: TokenValidationBlock | null;
}

export interface TokenChipProps {
  /** EVM address, 42-char hex. Used as DeterministicAvatar seed and shortAddr fallback. */
  token_address: string;
  /** Chain id — reserved for future chain-icon enrichment. Currently unused in render
   *  (chain identity surfaces via a sibling ChainBadge in the parent layout). */
  chain_id: number;
  /** Nullable per R8: enricher may not have resolved metadata yet. */
  info: TokenInfo | null;
}

/**
 * Format USD shortened with k/M suffix. Used in validation badges to show
 * liquidity amount inline ("$1.2M", "$50k", "$0.01").
 */
function formatUsdCompact(v: number | null | undefined): string {
  if (v == null || !Number.isFinite(v)) return "—";
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `$${(v / 1_000_000).toFixed(2)}M`;
  if (abs >= 1_000)     return `$${(v / 1_000).toFixed(1)}k`;
  if (abs >= 1)         return `$${v.toFixed(2)}`;
  if (abs >= 0.01)      return `$${v.toFixed(2)}`;
  return `$${v.toFixed(4)}`;
}

interface BadgeSpec {
  label: string;
  className: string;
  emoji: string;
  title: string;
}

/**
 * Resolve which badge to render for a given TokenInfo. Priority:
 *   1. Validation Engine status when present (covers all 7 cases).
 *   2. Legacy `verified` boolean as fallback (pre-validation-engine payloads).
 *   3. Unknown (no badge).
 */
function resolveBadge(info: TokenInfo | null | undefined, symbol: string | null): BadgeSpec | null {
  const v = info?.validation;
  if (v) {
    // The Validation Engine has run. Use its status + score directly.
    const liqLabel = v.liquidity_usd != null ? ` ${formatUsdCompact(v.liquidity_usd)}` : "";
    const topReason = v.reasons && v.reasons.length > 0 ? v.reasons[0]!.note : "";
    switch (v.status) {
      case "VERIFIED":
        return {
          label: "✓",
          emoji: "✓",
          className: "bg-success/15 text-success border-success/40",
          title:
            `VERIFIED (score ${v.score}) — ${info?.registry_name ?? info?.registry_symbol ?? "in curated registry"}`
            + (v.registry_source ? ` · source: ${v.registry_source}` : ""),
        };
      case "VIABLE":
        return {
          label: `LIQ${liqLabel}`,
          emoji: "💧",
          className: "bg-info/15 text-info border-info/40",
          title:
            `VIABLE (score ${v.score}) — has real market activity` +
            (v.liquidity_usd != null ? ` · liquidity ${formatUsdCompact(v.liquidity_usd)}` : "") +
            (v.volume_24h_usd != null ? ` · 24h vol ${formatUsdCompact(v.volume_24h_usd)}` : "") +
            ` · ${v.pair_count ?? 0} pair(s)`,
        };
      case "LOW_LIQUIDITY":
        return {
          label: `LOW${liqLabel}`,
          emoji: "⚠",
          className: "bg-warning/15 text-warning border-warning/40",
          title:
            `LOW LIQUIDITY (score ${v.score}) — below trading threshold` +
            (v.liquidity_usd != null ? ` · liquidity ${formatUsdCompact(v.liquidity_usd)} < $5,000` : ""),
        };
      case "ILLIQUID":
        return {
          label: `ILLIQ${liqLabel}`,
          emoji: "🚫",
          className: "bg-destructive/15 text-destructive border-destructive/40",
          title:
            `ILLIQUID (score ${v.score}) — likely scam / wash trading / rugpull` +
            (v.liquidity_usd != null ? ` · liquidity ${formatUsdCompact(v.liquidity_usd)}` : "") +
            (topReason ? ` · ${topReason}` : ""),
        };
      case "NO_DATA":
        return {
          label: "NO MARKET",
          emoji: "❓",
          className: "bg-muted/40 text-muted-foreground border-border/60",
          title: `NO_DATA (score ${v.score}) — no DEX pair indexed; token might be brand-new or unlisted`,
        };
      case "INVALID":
        return {
          label: "NOT ERC20",
          emoji: "⛔",
          className: "bg-destructive/25 text-destructive border-destructive/60",
          title: `INVALID — address has no contract bytecode OR does not implement the ERC-20 standard`,
        };
      case "PENDING":
        return {
          label: "validating…",
          emoji: "⏳",
          className: "bg-muted/30 text-muted-foreground/80 border-border/40 italic",
          title: "PENDING — validation queued; result will appear on next refresh",
        };
    }
  }

  // Legacy fallback: payload predates the validation engine (no `validation`
  // field). Use the binary `verified` flag.
  if (info?.verified === true) {
    return {
      label: "✓",
      emoji: "✓",
      className: "bg-success/15 text-success border-success/40",
      title: info?.registry_name
        ? `Verified — ${info.registry_name} (${info.registry_symbol ?? symbol})`
        : "Verified by curated registry",
    };
  }
  if (info?.verified === false) {
    const isMismatch = info?.verified_notes?.includes("symbol-mismatch");
    return {
      label: "⚠ unverified",
      emoji: "⚠",
      className: "bg-destructive/15 text-destructive border-destructive/40",
      title: isMismatch
        ? `⚠ IMPERSONATION RISK — contract claims "${symbol}" but the canonical token at this address is "${info?.registry_symbol ?? "unknown"}". Do NOT trade.`
        : "⚠ UNVERIFIED — address not in curated registry.",
    };
  }
  return null;
}

function SymbolPlusAddress({
  avatar,
  symbol,
  token_address,
  info,
}: {
  avatar: React.ReactNode;
  symbol: string | null;
  token_address: string;
  /** Optional — when present, drives the validation badge. */
  info?: TokenInfo | null;
}) {
  const displaySymbol = symbol ?? "—";
  const badge = resolveBadge(info, symbol);

  // Symbol styling: green/normal for VERIFIED/VIABLE; warning/italic for
  // LOW_LIQUIDITY/PENDING; destructive/italic for ILLIQUID/INVALID/unverified.
  const status = info?.validation?.status;
  const symbolCls = symbol
    ? status === "VERIFIED" || status === "VIABLE"
      ? "text-foreground font-semibold"
      : status === "INVALID" || status === "ILLIQUID"
        ? "text-destructive font-semibold italic"
        : status === "LOW_LIQUIDITY"
          ? "text-warning font-semibold italic"
          : status === "NO_DATA"
            ? "text-muted-foreground font-semibold italic"
            : status === "PENDING"
              ? "text-muted-foreground/70 italic"
              // Legacy fallback path (no validation block)
              : info?.verified === false
                ? "text-muted-foreground/90 font-semibold italic"
                : "text-foreground font-semibold"
    : "text-muted-foreground/70 italic";

  return (
    <span className="inline-flex items-center gap-2 min-w-0">
      {avatar}
      <span className="flex flex-col min-w-0 leading-tight">
        <span className="flex items-center gap-1 min-w-0 flex-wrap">
          <span className={`text-xs ${symbolCls} truncate`} title={badge?.title ?? symbol ?? "metadata pending"}>
            {displaySymbol}
          </span>
          {badge && (
            <span
              className={`text-[8px] font-bold px-1 py-px rounded border uppercase tracking-wider shrink-0 ${badge.className}`}
              title={badge.title}
              aria-label={badge.title}
            >
              {badge.label}
            </span>
          )}
        </span>
        <span
          className="font-mono text-[10px] text-muted-foreground/80 truncate"
          title={token_address}
        >
          {shortAddr(token_address)}
        </span>
      </span>
    </span>
  );
}

export function TokenChip({ token_address, info }: TokenChipProps) {
  // Case D: enricher pending OR missing field (old API shape) — info not available.
  if (info == null) {
    return (
      <SymbolPlusAddress
        avatar={
          <DeterministicAvatar
            seed={token_address}
            className="size-6 rounded-full shrink-0"
          />
        }
        symbol={null}
        token_address={token_address}
        info={null}
      />
    );
  }

  const hasLogo = info.logo_url !== null && info.logo_url.length > 0;
  const hasSymbol = info.symbol !== null && info.symbol.length > 0;

  // Case A: logo available — render img with graceful onError fallback (browser-only).
  if (hasLogo) {
    const altLabel = hasSymbol ? info.symbol! : shortAddr(token_address);
    return (
      <SymbolPlusAddress
        avatar={
          <img
            src={info.logo_url!}
            alt={altLabel}
            width={24}
            height={24}
            className="size-6 rounded-full shrink-0 object-cover"
            onError={(e) => {
              (e.currentTarget as HTMLImageElement).style.display = "none";
            }}
          />
        }
        symbol={hasSymbol ? info.symbol : null}
        token_address={token_address}
        info={info}
      />
    );
  }

  // Case C: explicit failure OR Case B: symbol-only OR fallback.
  // All three share the same avatar+symbol+address layout; the only
  // difference is whether `symbol` is non-null.
  return (
    <SymbolPlusAddress
      avatar={
        <DeterministicAvatar
          seed={token_address}
          className="size-6 rounded-full shrink-0"
        />
      }
      symbol={hasSymbol ? info.symbol : null}
      token_address={token_address}
      info={info}
    />
  );
}

/**
 * =============================================================================
 * OMEGA USECONTRACTS HOOK — Infrastructure Abstraction
 * =============================================================================
 *
 * Encapsulates fetch logic for contract entities.
 * Eliminates API-leaks from omega-s5 pages.
 *
 * Pattern: Hook → api-client → Edge Worker
 */

"use client";

import { useEffect, useState } from "react";
import { getApiBaseUrl } from "@/lib/api-client";
import type { ContractEntity } from "@/lib/registries/types-omni";

// =============================================================================
// Types
// =============================================================================

export interface UseContractsOptions {
  /** Filter by contract kind (e.g., "factory", "resolution_core") */
  contractKind?: string;
  /** Filter by multiple contract kinds */
  contractKinds?: Array<ContractEntity["contract_kind"]>;
}

export interface UseContractsResult {
  data: ContractEntity[];
  isLoading: boolean;
  error: string | null;
  /** Refetch manually */
  refetch: () => Promise<void>;
}

// =============================================================================
// Hook Implementation
// =============================================================================

/**
 * Hook to fetch contract entities from /api/contracts.
 *
 * @example
 * ```tsx
 * function WalletsPage() {
 *   const { data, isLoading, error } = useContracts({
 *     contractKinds: ["wallet_topology", "gas_sponsor"]
 *   });
 * }
 * ```
 */
export function useContracts(options: UseContractsOptions = {}): UseContractsResult {
  const { contractKind, contractKinds } = options;

  const [data, setData] = useState<ContractEntity[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    setIsLoading(true);
    setError(null);

    try {
      // Build URL with optional filter
      let url = `${getApiBaseUrl()}/api/contracts`;
      if (contractKind) {
        url += `?contract_kind=${encodeURIComponent(contractKind)}`;
      }

      const res = await fetch(url, {
        headers: { accept: "application/json" },
        signal: AbortSignal.timeout(5000),
      });

      if (!res.ok) {
        setError(`HTTP ${res.status}`);
        return;
      }

      const json = await res.json();
      let rows: ContractEntity[] = Array.isArray(json?.rows) ? json.rows : [];

      // Client-side filter if multiple kinds specified
      if (contractKinds && contractKinds.length > 0) {
        rows = rows.filter((c) => contractKinds.includes(c.contract_kind));
      }

      setData(rows);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [contractKind]); // Re-fetch if contractKind changes

  return {
    data,
    isLoading,
    error,
    refetch: fetchData,
  };
}

"use client";

/**
 * useWebSocket — generic typed WebSocket hook with auto-reconnect.
 *
 * Architecture:
 *   - Wraps the native WebSocket API with automatic reconnection.
 *   - Returns a typed messages ring buffer (last 100) + connection status.
 *   - JSON parsing is handled internally; malformed messages are dropped
 *     with a console warning (not a fatal error).
 *   - Auto-reconnect uses a fixed 5s backoff to avoid reconnect storms.
 *   - Cleanup on unmount: closes the socket and clears all timers.
 *
 * R1 compliant: all WebSocket access is inside useEffect; initial render
 *   is pure useState(initial) — identical to the SSR snapshot.
 * R8 fail-honest: connection status is surfaced verbatim; we never fake
 *   "connected" when the socket is not open.
 */

import { useEffect, useRef, useState, useCallback } from "react";

export type WsConnectionStatus =
  | "connecting"
  | "open"
  | "closed"
  | "error"
  | "reconnecting";

export interface UseWebSocketOptions {
  /** Auto-reconnect on close/error. Default: true. */
  autoReconnect?: boolean;
  /** Reconnect backoff in ms. Default: 5000. */
  reconnectBackoffMs?: number;
  /** Max messages to keep in the ring buffer. Default: 100. */
  maxMessages?: number;
  /** Optional subprotocols for the WebSocket constructor. */
  protocols?: string | string[];
}

export interface UseWebSocketResult<T> {
  /** Last N messages received (most recent first). */
  messages: T[];
  /** Current WebSocket connection status. */
  status: WsConnectionStatus;
  /** Send a message to the server (no-op when not open). */
  send: (data: string | object) => void;
  /** Manually close the connection. */
  close: () => void;
  /** Latest error message, if any. */
  lastError: string | null;
}

const DEFAULT_MAX_MESSAGES = 100;
const DEFAULT_RECONNECT_BACKOFF_MS = 5000;

/**
 * Generic WebSocket hook with auto-reconnect and typed message buffer.
 *
 * @param url — WebSocket URL (e.g. "wss://api.example.com/ws"). Pass null to keep the socket closed.
 * @param options — Configuration for reconnect, buffer size, protocols.
 *
 * @example
 * ```tsx
 * const { messages, status, send } = useWebSocket<MyEventType>("wss://api.example.com/ws");
 * ```
 */
export function useWebSocket<T = unknown>(
  url: string | null,
  options: UseWebSocketOptions = {},
): UseWebSocketResult<T> {
  const {
    autoReconnect = true,
    reconnectBackoffMs = DEFAULT_RECONNECT_BACKOFF_MS,
    maxMessages = DEFAULT_MAX_MESSAGES,
    protocols,
  } = options;

  const [messages, setMessages] = useState<T[]>([]);
  const [status, setStatus] = useState<WsConnectionStatus>("connecting");
  const [lastError, setLastError] = useState<string | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const aliveRef = useRef(true);
  const maxMessagesRef = useRef(maxMessages);
  const urlRef = useRef(url);

  // Keep refs in sync without triggering re-renders.
  useEffect(() => {
    maxMessagesRef.current = maxMessages;
    urlRef.current = url;
  }, [maxMessages, url]);

  const closeSocket = useCallback(() => {
    const ws = wsRef.current;
    if (ws) {
      // Suppress the onclose handler so it doesn't trigger reconnect
      // when we're doing an intentional close.
      ws.onclose = null;
      ws.onerror = null;
      ws.onmessage = null;
      ws.onopen = null;
      if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
        ws.close();
      }
      wsRef.current = null;
    }
  }, []);

  const connect = useCallback(() => {
    if (typeof window === "undefined") return;
    if (!urlRef.current) return;
    if (!aliveRef.current) return;

    // Close any existing socket first.
    closeSocket();

    setStatus("connecting");
    setLastError(null);

    try {
      const ws = protocols
        ? new WebSocket(urlRef.current, protocols)
        : new WebSocket(urlRef.current);

      wsRef.current = ws;

      ws.onopen = () => {
        if (!aliveRef.current) {
          ws.close();
          return;
        }
        setStatus("open");
        setLastError(null);
      };

      ws.onmessage = (event: MessageEvent) => {
        if (!aliveRef.current) return;

        let parsed: T;
        try {
          parsed =
            typeof event.data === "string"
              ? (JSON.parse(event.data) as T)
              : (event.data as T);
        } catch {
          // Malformed JSON — drop with a warning.
          // eslint-disable-next-line no-console
          console.warn("[useWebSocket] dropped malformed JSON message:", event.data?.slice(0, 200));
          return;
        }

        setMessages((prev) => {
          const next = [parsed, ...prev];
          if (next.length > maxMessagesRef.current) {
            return next.slice(0, maxMessagesRef.current);
          }
          return next;
        });
      };

      ws.onerror = () => {
        if (!aliveRef.current) return;
        setStatus("error");
        setLastError("WebSocket error occurred");
      };

      ws.onclose = () => {
        if (!aliveRef.current) return;
        setStatus("closed");

        if (autoReconnect && aliveRef.current) {
          setStatus("reconnecting");
          reconnectTimerRef.current = setTimeout(() => {
            if (aliveRef.current) {
              connect();
            }
          }, reconnectBackoffMs);
        }
      };
    } catch (err) {
      if (!aliveRef.current) return;
      setStatus("error");
      setLastError((err as Error).message ?? "WebSocket construction failed");

      if (autoReconnect && aliveRef.current) {
        setStatus("reconnecting");
        reconnectTimerRef.current = setTimeout(() => {
          if (aliveRef.current) {
            connect();
          }
        }, reconnectBackoffMs);
      }
    }
  }, [autoReconnect, reconnectBackoffMs, closeSocket]);

  // Main effect: connect when url changes, cleanup on unmount.
  useEffect(() => {
    aliveRef.current = true;

    if (url) {
      connect();
    } else {
      setStatus("closed");
    }

    return () => {
      aliveRef.current = false;
      if (reconnectTimerRef.current) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      closeSocket();
    };
  }, [url, connect, closeSocket]);

  const send = useCallback(
    (data: string | object) => {
      const ws = wsRef.current;
      if (!ws || ws.readyState !== WebSocket.OPEN) {
        // eslint-disable-next-line no-console
        console.warn("[useWebSocket] send() called but socket is not open");
        return;
      }
      const payload = typeof data === "string" ? data : JSON.stringify(data);
      ws.send(payload);
    },
    [],
  );

  const close = useCallback(() => {
    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current);
      reconnectTimerRef.current = null;
    }
    closeSocket();
    setStatus("closed");
  }, [closeSocket]);

  return { messages, status, send, close, lastError };
}
